package com.wedo.backend.poll.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="poll_votes") public class PollVoteEntity { @Id private UUID id; @Column(name="poll_id",nullable=false) private UUID pollId; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected PollVoteEntity(){} public PollVoteEntity(UUID id,UUID pollId,UUID userId,Instant now){this.id=id;this.pollId=pollId;this.userId=userId;this.createdAt=now;this.updatedAt=now;} public UUID getId(){return id;} public UUID getPollId(){return pollId;} public UUID getUserId(){return userId;} public void touch(Instant now){updatedAt=now;} }
